def legacy_decisions(apps, schema_editor):
    """Decyzje sprzed pamięci sprzeciwu: z dziennika audytu, a gdy go brak, z bieżącego werdyktu.
    Powód nieznany, bez migawki. Nie wyciągamy uzasadnień z notatek."""
    Edge = apps.get_model("similarity", "Edge")
    EdgeDecision = apps.get_model("similarity", "EdgeDecision")
    AuditLog = apps.get_model("evidence", "AuditLog")
    edges = {e.pk: e for e in Edge.objects.all()}
    covered = set()
    previous: dict[int, str] = {}
    for log in AuditLog.objects.filter(action="edge.verdict", object_type="edge").order_by("created_at", "id"):
        edge = edges.get(int(log.object_id)) if log.object_id.isdigit() else None
        if edge is None:
            continue
        verdict = (log.payload or {}).get("verdict", "")
        EdgeDecision.objects.create(
            edge=edge, ad_a_id=edge.ad_a_id, ad_b_id=edge.ad_b_id, verdict=verdict,
            previous_verdict=previous.get(edge.pk, ""), reason="unknown", note=(log.payload or {}).get("note", ""),
            legacy=True, user_id=log.user_id, created_at=log.created_at,
        )
        previous[edge.pk] = verdict
        covered.add(edge.pk)
    for edge in edges.values():
        if edge.verdict and edge.pk not in covered:
            EdgeDecision.objects.create(
                edge=edge, ad_a_id=edge.ad_a_id, ad_b_id=edge.ad_b_id, verdict=edge.verdict, reason="unknown",
                note=edge.verdict_note, legacy=True, user_id=edge.verdict_by_id, created_at=edge.verdict_at or edge.updated_at,
            )
    Edge.objects.exclude(verdict="").update(verdict_reason="unknown")


